package com.bank.repair;

import java.util.logging.*;

public class CycleStartDemo {
    private static final Logger log = Logger.getLogger(CycleStartDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        ChainRepairTool tool = new ChainRepairTool();

        // T1→T2→T3→T4→T5→(back to T3): cycle starts at T3
        TxnNode t1 = new TxnNode("T1"), t2 = new TxnNode("T2"),
                t3 = new TxnNode("T3"), t4 = new TxnNode("T4"), t5 = new TxnNode("T5");
        t1.next = t2; t2.next = t3; t3.next = t4; t4.next = t5; t5.next = t3;

        TxnNode start = tool.findCycleStart(t1);
        log.info(() -> "Cycle starts at: " + (start == null ? "none" : start.id));
    }
}

