class ChainRepairTool {
    private static final Logger log = Logger.getLogger(ChainRepairTool.class.getName());

    // Floyd phase 1 (meet), phase 2 (align from head). O(n), O(1).
    TxnNode findCycleStart(TxnNode head) {
        TxnNode slow = head, fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
            if (slow == fast) {                 // meeting inside the loop
                TxnNode p = head;
                while (p != slow) {             // walk both by one
                    p = p.next;
                    slow = slow.next;
                }
                log.warning(() -> "Cycle entry at " + p.id);
                return p;                       // entry node
            }
        }
        return null;                            // no cycle
    }
}

